contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function test(string calldata description) external {
        // The test contract has never been granted admin rights.
        require(!c.isAdmin(address(this)), "caller must be a non-admin");

        bool callSucceeded = true;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            callSucceeded = false;
        } else {
            callSucceeded = true;
        }

        // General rule: a call to newEmergencyOracle succeeds if and only if
        // the caller is an admin. A non-admin call must revert.
        assert(callSucceeded == c.isAdmin(address(this)));
    }
}

