// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EmergencyOracleFactory} from "../src/EmergencyOracleFactory.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EmergencyOracleFactory c;

    function setUp() public {
        c = new EmergencyOracleFactory();
    }

    function _test(string memory description) internal {
        vm.assume(!c.isAdmin(address(this)));
        bool callSucceeded = true;
        try c.newEmergencyOracle(description) {
            callSucceeded = true;
        } catch {
            callSucceeded = false;
        }
        assertTrue(callSucceeded == c.isAdmin(address(this)));
    }

    function testFuzz_test(string memory description) public {
        _test(description);
    }

    receive() external payable {}
}
